/**
 * Data layer for the Aggregate Stats views — STATIC build.
 *
 * Loads two baked JSON files once (public/data, regenerated by server scripts/bake-static.ts)
 * and serves everything client-side, so the deployed site needs no backend or database.
 *
 * Backend honesty: only top-division LEAGUE titles exist (no cup/other trophies), so `cup`/`oth`
 * are 0 and a manager's cabinet holds only championships. Data is a frozen snapshot — re-bake +
 * re-deploy to refresh.
 */

export interface Country {
  code: string;
  name: string;
}

export interface Manager {
  userId: number;
  login: string;
  c: string;
  team: string;
  lg: number;
  main: number; // main national cup wins (attributed)
  sec: number; // secondary/consolation cup wins (attributed)
  oth: number;
  lastWin: boolean; // holds a title in their country's most recent season (reigning champion)
}

export interface TrophyItem {
  main: string;
  sub: string;
  season: string;
}

export interface TrophyCabinet {
  champ: TrophyItem[];
  main: TrophyItem[];
  sec: TrophyItem[];
  other: TrophyItem[];
}

export interface Winner {
  season: number;
  club: string;
  manager: string;
}

export interface CupWinner {
  season: number;
  club: string;
  manager: string;
}

export interface CupRoll {
  cupId: number;
  cupName: string;
  isMain: boolean;
  cupLevel: number;
  cupLevelIndex: number;
  winners: CupWinner[];
}

export interface CupCountry {
  leagueId: number;
  country: string;
  cups: CupRoll[];
}

interface RawCup {
  country: string;
  season: number;
  club: string;
  cup: string;
}
interface RawManager {
  userId: number;
  userName: string;
  nationality: string;
  lg: number;
  main: number;
  sec: number;
  titles: Array<{ country: string; season: number; club: string }>;
  cupsMain: RawCup[];
  cupsSec: RawCup[];
}
interface RawLeague {
  leagueId: number;
  country: string;
  champions: Array<{ season: number; club: string; manager: string }>;
}

let bundle: Promise<{ managers: RawManager[]; leagues: RawLeague[] }> | null = null;
function load() {
  if (!bundle) {
    bundle = Promise.all([
      fetch('/data/managers.json').then((r) => r.json() as Promise<RawManager[]>),
      fetch('/data/leagues.json').then((r) => r.json() as Promise<RawLeague[]>),
    ]).then(([managers, leagues]) => ({ managers, leagues }));
  }
  return bundle;
}

// Cups load lazily on their own — the Cup winners view is the only consumer, and cups.json is
// large, so we don't pull it into the initial bundle. Missing file (older bake) → empty list.
let cupsBundle: Promise<CupCountry[]> | null = null;
function loadCups() {
  if (!cupsBundle) {
    cupsBundle = fetch('/data/cups.json')
      .then((r) => (r.ok ? (r.json() as Promise<CupCountry[]>) : []))
      .catch(() => []);
  }
  return cupsBundle;
}

export async function getCupCountries(): Promise<Country[]> {
  const cups = await loadCups();
  return cups.map((c) => ({ code: String(c.leagueId), name: c.country }));
}

export async function getCups(leagueId: string): Promise<CupRoll[]> {
  const cups = await loadCups();
  return cups.find((c) => String(c.leagueId) === leagueId)?.cups ?? [];
}

export async function getNationalities(): Promise<Country[]> {
  const { managers } = await load();
  const counts = new Map<string, number>();
  for (const m of managers) counts.set(m.nationality, (counts.get(m.nationality) ?? 0) + 1);
  return [...counts.entries()]
    .filter(([n]) => n && n !== 'Unknown')
    .sort((a, b) => b[1] - a[1])
    .map(([nationality, n]) => ({ code: nationality, name: `${nationality} (${n})` }));
}

export async function getLeagues(): Promise<Country[]> {
  const { leagues } = await load();
  return leagues.map((l) => ({ code: String(l.leagueId), name: l.country }));
}

export async function getManagers(nationality?: string): Promise<Manager[]> {
  const { managers, leagues } = await load();

  // Each country runs its own season clock, so "last winner" is per-country: the latest
  // season present in that country's roll of honour. Join on country name (both sides derive
  // from LeagueChampion.countryName in the bake).
  const latestByCountry = new Map<string, number>();
  for (const l of leagues)
    for (const c of l.champions) {
      const cur = latestByCountry.get(l.country);
      if (cur === undefined || c.season > cur) latestByCountry.set(l.country, c.season);
    }

  return managers
    .filter((m) => !nationality || nationality === 'ALL' || m.nationality === nationality)
    .map((m) => ({
      userId: m.userId,
      login: m.userName,
      c: m.nationality,
      team: '',
      lg: m.lg,
      main: m.main ?? 0,
      sec: m.sec ?? 0,
      oth: 0,
      lastWin: (m.titles ?? []).some((t) => latestByCountry.get(t.country) === t.season),
    }));
}

export async function getCabinet(userId: number): Promise<TrophyCabinet> {
  const { managers } = await load();
  const m = managers.find((x) => x.userId === userId);
  const champ = (m?.titles ?? []).map((t) => ({ main: `${t.country} champions`, sub: t.club, season: 'S' + t.season }));
  const cupItems = (cups?: RawCup[]) => (cups ?? []).map((t) => ({ main: t.cup, sub: t.club, season: 'S' + t.season }));
  return { champ, main: cupItems(m?.cupsMain), sec: cupItems(m?.cupsSec), other: [] };
}

export async function getWinners(leagueId: string): Promise<Winner[]> {
  const { leagues } = await load();
  const l = leagues.find((x) => String(x.leagueId) === leagueId);
  return l ? l.champions : [];
}
